from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            events[b].append((a, i))

        largest = second_largest = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for a, pair_id in events[right]:
                if a > largest:
                    second_largest, largest, largest_id = largest, a, pair_id
                elif a > second_largest:
                    second_largest = a

            # The largest a among pairs ending by `right` is the minimum
            # allowed starting position minus one.
            base += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second_largest

        return base + max(gains)

