from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            events[b].append((a, i))
        top = second = 0
        top_id = -1
        gain = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for a, i in events[r]:
                if a > top:
                    second, top, top_id = top, a, i
                elif a > second:
                    second = a
            base += r - top
            if top_id != -1:
                gain[top_id] += top - second
        return base + max(gain)

