from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        processes.append(tuple(data[pos:pos + 4]))
        pos += 4

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            period = b // gcd(a, b)
            limit = (target + a - 1) // a
            best = 10**30
            for r in range(min(period, limit + 1)):
                largest = r + (limit - r) // period * period
                for x in (r, largest, largest - period):
                    if x < 0 or x > limit:
                        continue
                    y = max(0, (target - a * x + b - 1) // b)
                    best = min(best, x * p + y * q)
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

