class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        ans = 0
        for ones in range(1, n + 1):
            x = ones
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            if steps > k - 1:
                continue
            pref = 0
            cnt = 0
            for i, ch in enumerate(s):
                rem = n - i - 1
                if ch == '1':
                    need = ones - pref
                    if 0 <= need <= rem:
                        cnt += comb(rem, need)
                    pref += 1
                if pref > ones:
                    break
            ans += cnt
        return ans % MOD

