import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    graph = data[1:]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i, row in enumerate(graph):
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    dist = [[-1] * n for _ in range(n)]
    q = deque()
    reached = 0

    # The empty string gives every diagonal pair distance zero.
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
        reached += 1

    # A single edge gives a palindrome of length one.
    for i in range(n):
        for c in range(26):
            for j in outgoing[i][c]:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))
                    reached += 1

    total = n * n
    while q and reached < total:
        a, b = q.popleft()
        nd = dist[a][b] + 2
        # Enclose a palindrome path a -> b with equally labeled edges.
        for c in range(26):
            left = incoming[a][c]
            right = outgoing[b][c]
            for i in left:
                row = dist[i]
                for j in right:
                    if row[j] == -1:
                        row[j] = nd
                        q.append((i, j))
                        reached += 1

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

