import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))

        total = math.factorial(len(odds)) * math.factorial(len(evens))
        if len(odds) == len(evens):
            total *= 2
        if k > total:
            return []

        result = []
        previous_odd = None
        for pos in range(n):
            remaining_positions = n - pos - 1
            chosen = False
            for value in range(1, n + 1):
                is_odd = value % 2 == 1
                pool = odds if is_odd else evens
                if value not in pool:
                    continue
                if previous_odd is not None and is_odd == previous_odd:
                    continue

                rem_odds = len(odds) - int(is_odd)
                rem_evens = len(evens) - int(not is_odd)
                next_is_odd = not is_odd
                needed_odds = ((remaining_positions + 1) // 2
                               if next_is_odd else remaining_positions // 2)
                needed_evens = remaining_positions - needed_odds

                if rem_odds == needed_odds and rem_evens == needed_evens:
                    block = math.factorial(rem_odds) * math.factorial(rem_evens)
                else:
                    block = 0

                if k > block:
                    k -= block
                else:
                    result.append(value)
                    pool.remove(value)
                    previous_odd = is_odd
                    chosen = True
                    break
            if not chosen:
                return []
        return result

