class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # The digit at half-position p contributes these powers of ten
        # to the full number (one power at the center).
        coeff = []
        for p in range(m):
            if p == n - 1 - p:
                c = pow(10, p, k)
            else:
                c = (pow(10, p, k) + pow(10, n - 1 - p, k)) % k
            coeff.append(c)

        # dp[i][r]: using positions i..m-1, residue r is achievable.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            row = bytearray(k)
            nxt = dp[i + 1]
            c = coeff[i]
            for r in range(k):
                if nxt[r]:
                    for digit in range(10):
                        row[(r + c * digit) % k] = 1
            dp[i] = row

        # Greedily maximize each left-half digit while preserving feasibility.
        half = []
        residue = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-residue - c * digit) % k
                if dp[i + 1][needed]:
                    half.append(str(digit))
                    residue = (residue + c * digit) % k
                    break

        left = ''.join(half)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

