class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        answer = len(s)
        # For a fixed positive final frequency k, process letters from left to
        # right. dp[f] is the least cost when f characters are forwarded from
        # the current letter to its successor.
        for k in range(1, max(counts) + 1):
            dp = {0: 0}
            for count in counts:
                ndp = {}
                for incoming, cost_so_far in dp.items():
                    available = count + incoming
                    for outgoing in range(available + 1):
                        remaining = available - outgoing
                        # Make this letter absent (delete all remaining), or
                        # make it occur k times (insert/delete as needed).
                        local = min(remaining, abs(remaining - k))
                        total = cost_so_far + outgoing + local
                        if total < ndp.get(outgoing, 10**9):
                            ndp[outgoing] = total
                dp = ndp
            answer = min(answer, dp.get(0, 10**9))
        return answer

