from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first = p.index('*')
        second = p.index('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])

        def occurrences(t: str):
            if not t:
                return list(range(n + 1))

            m = len(t)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                    prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == m:
                        result.append(i - m + 1)
                        j = prefix[j - 1]
            return result

        positions = [occurrences(part) for part in parts]
        lengths = [len(part) for part in parts]
        middle, last = positions[1], positions[2]
        best = n + 1

        for start in positions[0]:
            i = bisect_left(middle, start + lengths[0])
            if i == len(middle):
                continue
            mid_start = middle[i]
            j = bisect_left(last, mid_start + lengths[1])
            if j == len(last):
                continue
            end_start = last[j]
            best = min(best, end_start + lengths[2] - start)

        return -1 if best == n + 1 else best

