class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        a = [0] * n
        b = [0] * n
        a[0], b[0] = energyDrinkA[0], energyDrinkB[0]
        for i in range(1, n):
            a[i] = energyDrinkA[i] + max(a[i-1], b[i-2] if i >= 2 else 0)
            b[i] = energyDrinkB[i] + max(b[i-1], a[i-2] if i >= 2 else 0)
        return max(a[-1], b[-1])

