class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        pref = 0
        ans = None
        mins[0] = 0
        for j, x in enumerate(nums, 1):
            pref += x
            r = j % k
            if mins[r] is not None:
                cand = pref - mins[r]
                if ans is None or cand > ans:
                    ans = cand
            if mins[r] is None or pref < mins[r]:
                mins[r] = pref
        return ans

