class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        lines = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(new_line, node, left, right):
            current = lines[node]
            if current is None:
                lines[node] = new_line
                return

            mid = (left + right) // 2
            if value(new_line, mid) > value(current, mid):
                lines[node], new_line = new_line, current
                current = lines[node]

            if left == right:
                return
            if value(new_line, left) > value(current, left):
                add(new_line, node * 2, left, mid)
            elif value(new_line, right) > value(current, right):
                add(new_line, node * 2 + 1, mid + 1, right)

        def query(x, node, left, right):
            best = value(lines[node], x) if lines[node] is not None else -10**30
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                return max(best, query(x, node * 2, left, mid))
            return max(best, query(x, node * 2 + 1, mid + 1, right))

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            answer = query(j, 1, 0, n - 1)
            add((nums[j], answer - j * nums[j]), 1, 0, n - 1)
        return answer

