import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            d = 3
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 2
            return True

        if is_prime(n) or is_prime(m):
            return -1

        powers = [10 ** i for i in range(len(str(n)))]
        dist = {n: n}  # The initial value is included in the transformation cost.
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for p in powers:
                digit = (x // p) % 10
                for delta in (-1, 1):
                    if 0 <= digit + delta <= 9:
                        y = x + delta * p
                        if not is_prime(y):
                            new_cost = cost + y
                            if new_cost < dist.get(y, float('inf')):
                                dist[y] = new_cost
                                heapq.heappush(heap, (new_cost, y))

        return -1

