class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3: return 0
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right: z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]: z[i] += 1
            if i + z[i] > right: left, right = i, i + z[i]
        ans = 0
        nxt = [0] * n
        for i in range(n - 2, 0, -1):
            cur = [0] * n
            maxj = (n + i) // 2
            first = z[i] >= i
            if first: ans += max(0, n - max(2 * i, i + 1))
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]: cur[j] = 1 + nxt[j + 1] if j + 1 < n else 1
            for j in range(i + 1, min(n - 1, maxj) + 1):
                if (not first or j < 2 * i) and cur[j] >= j - i:
                    ans += 1
            nxt = cur
        return ans

