        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]
        ans = 0
        nextrow = [0] * n
        for i in range(n - 2, 0, -1):
            cur = [0] * n
            maxj = (n + i) // 2
            if z[i] >= i:
                ans += max(0, n - max(2 * i, i + 1))
                for j in range(n - 1, i, -1):
                    if nums[i] == nums[j]:
                        cur[j] = 1 + nextrow[j + 1] if j + 1 < n else 1
            else:
                for j in range(min(n - 1, maxj), i, -1):
                    if nums[i] == nums[j]:
                        v = 1 + nextrow[j + 1] if j + 1 < n else 1
                        cur[j] = v
                        if v >= j - i:
                            ans += 1
            if z[i] >= i:
                # second condition not counted in this branch
                for j in range(min(n - 1, maxj), i, -1):
                    if nums[i] == nums[j] and cur[j] >= j - i:
                        ans += 1
            nextrow = cur
        return ans

