from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            # Keep this source character without using it in the subsequence.
            ndp = dp[:]

            # Or remove it, if its original index is permitted.
            if i in targets:
                for j in range(m + 1):
                    if dp[j] != neg:
                        ndp[j] = max(ndp[j], dp[j] + 1)

            # Or use it to match the next pattern character.
            for j in range(1, m + 1):
                if ch == pattern[j - 1] and dp[j - 1] != neg:
                    ndp[j] = max(ndp[j], dp[j - 1])
            dp = ndp

        return dp[m]

