from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse incoming edges from 0, which discovers nodes that can reach 0.
        reverse_graph = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse_graph[b].append((a, w))
            weights.append(w)

        candidates = sorted(set(weights))

        def feasible(max_weight: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for predecessor, weight in reverse_graph[v]:
                    if weight <= max_weight and not seen[predecessor]:
                        seen[predecessor] = 1
                        reached += 1
                        stack.append(predecessor)
            return reached == n

        if not feasible(candidates[-1]):
            return -1

        left, right = 0, len(candidates) - 1
        while left < right:
            mid = (left + right) // 2
            if feasible(candidates[mid]):
                right = mid
            else:
                left = mid + 1
        return candidates[left]

