                        if any(x1 <= x <= x2 and y1 <= y <= y2 and (x,y) not in corners for x,y in p):
                            continue
                        ans = max(ans, (x2-x1)*(y2-y1))
        return ans

if __name__ == '__main__':
    s=Solution()
    assert s.maxRectangleArea([[1,1],[1,3],[3,1],[3,3]]) == 4
    assert s.maxRectangleArea([[1,1],[1,3],[3,1],[3,3],[2,2]]) == -1
    assert s.maxRectangleArea([[1,1],[1,3],[3,1],[3,3],[1,2],[3,2]]) == 2

from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(point) for point in points}
        xs = sorted({x for x, y in point_set})
        ys = sorted({y for x, y in point_set})
        best = -1

        for i, x1 in enumerate(xs):
            for x2 in xs[i + 1:]:
                for j, y1 in enumerate(ys):
                    for y2 in ys[j + 1:]:
                        corners = ((x1, y1), (x1, y2), (x2, y1), (x2, y2))
                        if not all(corner in point_set for corner in corners):
                            continue

                        # Reject if any other given point lies inside or on the boundary.
                        if any(
                            x1 <= x <= x2 and y1 <= y <= y2 and (x, y) not in corners
                            for x, y in point_set
                        ):
                            continue

                        best = max(best, (x2 - x1) * (y2 - y1))

        return best

